declare namespace Rose.Alert {

    /**
     * 模块名字
     */
    export const Name: string;

    /**
     * 模块消息
     */
    export enum Message {
        /**
         * 消息弹框
         */
        showMessaage = "showMessaage",
        /**
        * 隐藏种子存储数据
        */
        showCanvas = "showCanvas",
    }

    /**
     * 消息枚举
     */
    export enum MessageBoxType {
        /**
         * 无类型信息
         */
        None = 0,
        /**
         * 提示信息
         */
        Info = 1,
        /**
         * 疑问信息
         */
        Question = 2,
        /**
        * 警告信息
        */
        Warn = 3,
        /**
         * 错误信息
         */
        Error = 4,
    }

    /**
     * 启动模块
     */
    export function Start(): void

    /**
     * 关闭模块
     */
    export function Stop(): void

    /**
     * 是否有警告框
     */
    export function HasView(): boolean;

    /**
     * 显示
     * @param view 
     */
    export function ShowCanvas(view: fairygui.GComponent): void;

    /**
     * 关闭
     * @param view 
     */
    export function CloseCanvas(view: fairygui.GComponent): void;

    /**
     * 消息警告消息
     * @param info 标题
     * @param msg 内容
     * @param type 警告框类型
     * @param btnText 按钮文字
     * @param callBack 回调
     */
    export function ShowMessage(info: string, msg: string, type: Rose.Alert.MessageBoxType, btnText: string, callBack?: (str: cc.Event.EventCustom) => void): void;

    /**
     * 简单信息提示
     * @param msg 
     */
    export function ShowSimpleMsg(msg: string,): void;
}
